import json,hashlib
D={'pages':[],'units':[],'boundary_notes':[],'review_notes':[],'completed':False}
OUT='/workspace/scratch/volume4/batch379-388.json'
def save():json.dump(D,open(OUT,'w'),ensure_ascii=False,indent=2)
def p(n,rows):
 pars=[]
 for i,(ar,ru) in enumerate(rows,1):
  id=f'v4-p{n:03}-{i:02}'
  pars.append(dict(id=id,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  D['units'].append(dict(id=id+'-ru',source_ids=[id],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 D['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=pars));save()
def merge(a,b):
 x=next(x for x in D['units'] if a in x['source_ids']);y=next(x for x in D['units'] if b in x['source_ids']);x['source_ids']+=y['source_ids'];x['printed_pages']+=y['printed_pages'];x['ar']+=' '+y['ar'];x['ru']+=' '+y['ru'];D['units'].remove(y);save()
p(379,[('والمقصود: أن العبد يقوى إخلاصه لله، وصدقه ومعاملته له، حتى لا يحب أن يطلع أحد من الخلق على حاله مع الله ومقامه معه، فهو يخفي أحواله غيرة عليها من أن تشوبها شائبة الأغيار، وأنفاسه خوفا عليها من المداخلة. وكان بعضهم إذا غلبه البكاء وعجز عن دفعه قال: لا إله إلا الله، ما أمر الزكام! فالصادق إذا غلب عليه الوجد والحال، وهاج من قلبه لواعج الشوق= أخلد إلى السكون ما أمكنه، فإن غلب أظهر ألما ووجعا يستر به حاله مع الله، كما أظهر إبراهيم الخليل عليه السلام لقومه أنه سقيم، حين أراد أن يفارقهم، ويرجع بذلك الوارد وتلك الحال إلى الآلهة الباطلة، فيجعلها جذاذا.','Смысл в том, что искренность раба перед Аллахом, его правдивость и обращение с Ним усиливаются настолько, что он не желает, чтобы кто-либо из творений узнал о его состоянии с Аллахом и стоянке перед Ним. Он скрывает свои состояния, ревниво оберегая их от примеси постороннего, а свои вздохи — из страха перед вмешательством. Когда плач одолевал одного из таких людей и он не мог его сдержать, он говорил: «Нет божества, кроме Аллаха! Как же горек насморк!» Когда правдивого человека охватывают сердечное переживание и особое состояние и в его сердце вспыхивает жгучее томление, он старается сохранять спокойствие, насколько может. Если же это его одолевает, он изображает боль и недомогание, чтобы скрыть своё состояние с Аллахом. Так Ибрахим, особый друг Аллаха, мир ему, показал своему народу, что болен, когда захотел покинуть их и с этим наплывом переживания и этим состоянием обратиться против ложных божеств, чтобы разбить их вдребезги.'),('فالصادقون يعملون في كتمان المعاني واجتناب الدعاوي، فظواهرهم ظواهر الناس، وقلوبهم مع الحق تعالى، لا تلتفت عنه يمنة ولا يسرة، فهم في واد، والناس في واد.','Правдивые трудятся над сокрытием внутренних смыслов и избегают притязаний. Внешне они подобны другим людям, а их сердца — со Всевышним Истинным и не отворачиваются от Него ни вправо, ни влево. Они в одной долине, а люди — в другой.'),('فقوله: (تلبيس أهل الغيرة على الأوقات بإخفائها) يعني: أنهم يغارون على الأوقات التي عمرت لهم بالله وصفت لهم أن يظهروها للناس، وإن اطلع غيرهم عليها من غير قصدهم لكشفها وإظهارها= لم يقدح ذلك في طريقهم، فلا يفزعون إلى الجحد والإنكار وشكاية الحال، بل يسعهم الإمساك عن الإظهار والجحد.','Его слова «Сокрытие, к которому прибегают ревниво оберегающие своё время, скрывая его» означают: они ревниво оберегают время, наполненное для них Аллахом и ставшее чистым, не желая показывать его людям. Если другие узнают об этом без их намерения раскрыть и показать это, их пути это не вредит. Поэтому они не прибегают к отречению, отрицанию и жалобам на своё состояние: им достаточно воздержаться и от раскрытия, и от отрицания.'),('قوله: (وعلى الكرامات بكتمانها)، يعني: أنهم يغارون على كراماتهم أن','Его слова «И чудесные дары — утаивая их» означают: они ревниво оберегают свои чудесные дары от того, чтобы')])
p(380,[('يعلم بها الناس، فهم يخفونها أبدا غيرة عليها، إلا إذا كان في إظهارها مصلحة راجحة من حجة أو حاجة، فلا يظهرونها إلا لحجة على مبطل، أو حاجة تقتضي إظهارها.','о них узнали люди, и постоянно скрывают их, ревниво оберегая. Исключение — когда в их раскрытии есть преобладающая польза: довод или нужда. Они раскрывают их лишь как довод против приверженца лжи либо по нужде, требующей раскрытия.'),('قوله: (والتلبيس بالمكاسب والأسباب، وتعليق الظاهر بالشواهد والمكاسب= تلبيس على العيون الكليلة والعقول العليلة)، يعني: أن التلبيس المذكور إنما يكون على أهل العيون الكليلة، أي أهل الإحساس الضعيف، والعقول العليلة هي المنحرفة التي لا تدرك الحق لمرض بها.','Его слова «Сокрытие посредством заработков и причин и связывание внешнего с наблюдаемыми проявлениями и заработками — сокрытие от слабых глаз и больных умов» означают: упомянутое сокрытие действует лишь на обладателей слабого зрения, то есть слабого восприятия. Больные же умы — это умы, отклонившиеся от истины и не постигающие её из-за своей болезни.'),('قوله: (مع تصحيح التحقيق عقدا وسلوكا ومعاينة)، يعني: أن هذه الطائفة يلبسون على أهل العيون الكليلة أحوالهم وكراماتهم بسترهم لها عنهم، مع كونهم قائمين بالتحقيق اعتقادا وسلوكا ومعاينة، فهم معتقدون للحق، سالكون الطريق الموصلة إلى المقصود، أهل مراقبة وشهود.','Его слова «При сохранении верного осуществления истины в убеждении, следовании пути и непосредственном созерцании» означают: эти люди скрывают от слабовидящих свои состояния и чудесные дары, утаивая их, но сами осуществляют истину в убеждениях, следовании пути и непосредственном созерцании. Они убеждены в истине, идут по пути, ведущему к цели, и обладают непрестанной внимательностью к Аллаху и созерцанием.'),('قوله: (وهذه الطائفة رحمة من الله على أهل التفرقة والأسباب في ملابستهم).','Его слова: «Эти люди — милость от Аллаха для пребывающих в раздельности и пользующихся причинами, когда они общаются с ними».'),('إنما كانوا رحمة من الله عليهم من وجهين:','Они являются для них милостью от Аллаха в двух отношениях:'),('أحدهما: أنهم ذاكرون لله بين الغافلين، وهم في وسطهم، فيرحمهم الله بهم، فإنهم القوم لا يشقى بهم جليسهم.','Во-первых, они поминают Аллаха среди беспечных, пребывая в их среде, и Аллах милует тех ради них. Это те люди, чей собеседник не будет несчастен благодаря общению с ними.'),('الثاني: أنهم لا يتركونهم في غفلاتهم، بل يقومون فيهم بالنصيحة لهم،','Во-вторых, они не оставляют их в беспечности, но наставляют их,')])
p(381,[('والأمر لهم بالمعروف والنهي عن المنكر، والدعوة لهم إلى الله، فيرحمون بهم، وينالون بهم سعادة الدنيا والآخرة، فهم يتصرفون مع الخلق بحكم العلم والشرع، وأحوالهم ومقاماتهم بينهم وبين الله خاصة.','побуждают к одобряемому и удерживают от порицаемого и призывают их к Аллаху. Поэтому через них те обретают милость и достигают счастья этого мира и Последней жизни. С творениями эти люди поступают согласно знанию и Закону, а их состояния и стоянки — лишь между ними и Аллахом.'),('قوله: (التلبيس الثالث: تلبيس أهل التمكين على العالم، ترحما عليهم بملابسة الأسباب، وتوسيعا على العالم لا على أنفسهم، وهذه درجة الأنبياء، ثم هي للأئمة الربانيين، الصادرين عن وادي الجمع، المشيرين عن عينه).','Его слова: «Третий вид сокрытия — сокрытие утверждённых от мира: из милосердия к людям они пользуются причинами, давая простор миру, а не себе. Это степень пророков, а затем — наставников, воспитанных Господом, исходящих из долины сосредоточения и указывающих на его источник».'),('هذا أيضا من النمط الأول، مما ينكر لفظه وإطلاقه غاية الإنكار، ويجب على أهل الإيمان هجر هذا اللفظ القبيح وإطلاقه في حق الأنبياء، وكيف تسمح مسامع المؤمن ليسمع أن الأنبياء لبسوا على الناس بأي اعتبار كان؟ سبحانك هذا بهتان عظيم! بل الرسل — صلوات الله وسلامه عليهم — كشفوا عن الناس التلبيس الذي لبسوه على أنفسهم، ولبسه عليهم طواغيتهم، جاؤوا بالبيان والبرهان.','Это также относится к первому виду выражений, которые следует решительно отвергать и по форме, и по употреблению. Верующие обязаны отказаться от этого безобразного выражения и от его применения к пророкам. Как слух верующего может спокойно принять слова о том, что пророки вводили людей в заблуждение, в каком бы смысле это ни утверждалось? Пречист Ты! Это великая клевета! Напротив, посланники, да благословит их Аллах и приветствует, сняли с людей то заблуждение, в которое те сами себя ввели и в которое их ввели их тагуты. Они принесли ясное разъяснение и доказательство.'),('وكان الناس في لبس عظيم فجاؤوا بالبيان فأظهروه\nوكان الناس في جهل شديد فجاؤوا باليقين فأذهبوه\nوكان الناس في كفر عظيم فجاؤوا بالرشاد فأبطلوه','Люди пребывали в великом замешательстве — они принесли разъяснение и явили его.\nЛюди пребывали в глубоком невежестве — они принесли убеждённость и устранили его.\nЛюди пребывали в великом неверии — они принесли верное руководство и упразднили его.')])
p(382,[('والمصنف رحمه الله من أثبت الناس قدما في مقام الإيمان بالرسل وتعظيمهم وما جاؤوا به، ولكن لبس عليه في ذلك ما لبس على غيره، والله يغفر لنا وله، ويجمع بيننا وبينه في دار كرامته.','Автор, да помилует его Аллах, — один из самых твёрдых людей на стоянке веры в посланников, почитания их и принесённого ими. Однако и его в этом вопросе постигло то заблуждение, которое постигло других. Да простит Аллах нас и его и да соединит нас с ним в обители Своего почёта.'),('وقد صرح بأن أهل التمكين هم الأنبياء والأئمة بعدهم، وجعل هذه الدرجة من التلبيس لهم، ثم فسرها بأنها تلبيس ترحم وتوسيع على العالم، ومقصوده: أنهم يأمرونهم بتعاطي الأسباب رحمة لهم وتوسيعا عليهم، مع علمهم بأنها لا تأثير لها في خلق ولا رزق، ولا ضر ولا نفع، ولا إعطاء ولا منع، بل الله وحده هو الخالق الرازق، الضار النافع، المعطي المانع، لكن لما علموا عجز الناس عن إدراك ذلك والتحقق به لبسوا عليهم وأمروهم بالأسباب رحمة بهم وتوسيعا عليهم.','Он прямо сказал, что утверждённые — это пророки и наставники после них, и отнёс к ним эту степень сокрытия. Затем он пояснил, что это сокрытие из милосердия, дающее людям простор. Он имеет в виду: они велят людям прибегать к причинам из милосердия к ним и ради облегчения для них, хотя знают, что причины не влияют ни на творение, ни на удел, ни на вред, ни на пользу, ни на дарование, ни на удержание. Один лишь Аллах — Творец, Дарующий удел, Причиняющий вред и пользу, Дарующий и Удерживающий. Но поскольку они знают, что люди неспособны постичь и осуществить это, они скрывают от них истину и велят им пользоваться причинами из милосердия к ним и ради облегчения для них.'),('فهذه الدرجة تتضمن الرجوع إلى الأسباب رحمة وتوسيعا، مع الانقطاع عن الالتفات إليها والوقوف معها تجريدا وتوحيدا.','Таким образом, эта степень включает возвращение к причинам из милосердия и ради облегчения, наряду с прекращением обращения внимания на них и задержки при них ради освобождения от всего постороннего и единобожия.'),('وقوله: (لا إلى أنفسهم) يعني: أن أمرهم بالأسباب إحسان إليهم، وتوسيع عليهم، لا لحظ الآمر وجر النفع إلى نفسه، بل لقصد الإحسان إلى الخلق وحصول النفع لهم. وهذا قريب، مع أن فيه ما فيه لمن تأمله، فإن من أمر غيره بمصلحته وقصد نفعه: فبنفسه بدأ، ولها نفع أولا، ومصلحتها حصل قبل مصلحة المأمور، والإحسان إلى نفسه قصد بإحسانه إلى غيره، فإنه عبد فقير محتاج، والله وحده هو الغني بذاته، الذي يحسن إلى خلقه لا لأجل معاوضة منهم، وأما المخلوق فإنه يريد العوض، لكن','Его слова «А не себе» означают: они велят людям пользоваться причинами, благодетельствуя им и облегчая им жизнь, а не ради доли для себя и собственной выгоды; их цель — благо творений и польза для них. Это близко к истине, хотя вдумчивый человек найдёт здесь, что обдумать. Ведь тот, кто велит другому делать полезное для него и желает ему пользы, начинает с себя: сначала приносит пользу собственной душе, и её благо достигается раньше блага того, кому велено. Благодетельствуя другому, он намеревается облагодетельствовать и себя, поскольку он — бедный, нуждающийся раб. Один лишь Аллах богат Сам по Себе и благодетельствует Своим творениям, не ожидая от них возмещения. Творение же желает возмещения, но')])
merge('v4-p379-04','v4-p380-01');merge('v4-p380-07','v4-p381-01')
p(383,[('الأعواض تتفاوت، ومن يطلب منه العوض يختلف.','возмещение бывает разным, и различается тот, от кого его ожидают.'),('والمقصود: أن قوله: (لا لأنفسهم) ليس على إطلاقه، وفي أثر إلهي: «ابن آدم، كل يريدك لنفسه، وأنا أريدك لك».','Смысл в том, что его слова «А не себе» не следует понимать безоговорочно. В одном божественном предании сказано: «Сын Адама! Все желают тебя ради себя, а Я желаю тебя ради тебя самого».'),('وقوله: (ثم هي للأئمة الربانيين، الصادرين عن وادي الجمع)، يعني: الذين فنوا في الجمع، ثم حصلوا في البقاء بعد الفناء، فذلك صدورهم عن وادي الجمع.','Его слова «А затем — наставников, воспитанных Господом, исходящих из долины сосредоточения» означают: тех, кто пережил фана в сосредоточении, а затем достиг пребывания после фана. Это и есть их выход из долины сосредоточения.'),('قوله: (المشيرين عن عينه)، يعني: الذين إذا أشاروا أشاروا عن عين لا عن علم، فإن الإشارة تختلف باختلاف مصدرها: فإشارة عن علم، وإشارة عن كشف، وإشارة عن شهود، وإشارة عن عين.','Его слова «Указывающих от его непосредственного видения» означают: когда они указывают, то исходят из непосредственного видения, а не из знания. Ведь указание различается в зависимости от источника: бывает указание, исходящее из знания, из раскрытия, из созерцания и из непосредственного видения.'),('فصل','Раздел'),('قد عرفت أن هذا الباب مبناه على محو الأسباب، وعدم الالتفات إليها والوقوف معها، ولهذا سمى المصنف نصبها «تلبيسا».','Ты уже узнал, что эта глава основана на устранении причин, отказе обращать на них внимание и останавливаться при них. Поэтому автор назвал их установление «введением в заблуждение».'),('ونحن نقول: إن الدين هو إثبات الأسباب، والوقوف معها، والنظر إليها، والالتفات إليها، وإنه لا دين إلا بذلك، كما لا حقيقة إلا به، فالحقيقة والشريعة مبناهما على إثباتها، لا على محوها، ولا ينكر الوقوف معها، فإن الوقوف معها فرض على كل مسلم، لا يتم إيمانه إلا بذلك. والله تعالى أمرنا بالوقوف معها، بمعنى أنا نثبت الحكم إذا وجدت، وننفيه إذا عدمت، ونستدل بها على حكمه الكوني، فوقوفنا معها بهذا الاعتبار هو مقتضى','Мы же говорим: религия заключается в признании причин, в том, чтобы считаться с ними, рассматривать их и обращать на них внимание. Без этого нет религии, как без этого нет и действительности. И действительность, и шариат основаны на признании причин, а не на их устранении. Нельзя порицать то, что человек считается с ними: это обязанность каждого мусульманина, без чего его вера не будет полной. Всевышний Аллах велел нам считаться с ними в том смысле, что мы утверждаем соответствующее следствие, когда они есть, и отрицаем его, когда их нет, и по ним судим о Его решении в мироздании. В этом отношении считаться с ними — требование')])
p(384,[('الحقيقة والشريعة، وهل يمكن حيوانا أن يعيش في هذه الدنيا إلا بوقوفه مع الأسباب؟ فينتجع مساقط غيثها ومواقع قطرها، ويرعى في خصبها دون جدبها، ويسالمها ولا يحاربها. وكيف وتنفسه في الهواء بها، وتحركه بها، وسمعه وبصره بها، وغذاؤه بها، ودواؤه بها، وهداه بها، وسعادته بها، وفلاحه بها، وضلاله وشقاؤه بالإعراض عنها وإلغائها. فأسعد الناس في الدارين: أقومهم بالأسباب الموصلة إلى مصالحهما، وأشقاهم في الدارين: أشدهم تعطيلا لأسبابهما.','действительности и шариата. Разве живое существо может жить в этом мире, не считаясь с причинами? Оно ищет места, где выпадают их дожди и капли, пасётся на их плодородных пастбищах, а не на бесплодных, мирится с ними, а не воюет. И как иначе, если благодаря им оно дышит воздухом и движется, слышит и видит, питается и лечится, получает верное руководство, счастье и успех? А заблуждение и несчастье приходят к нему вследствие пренебрежения причинами и их отмены. Счастливейшие из людей в обеих обителях — те, кто лучше всего пользуется причинами, ведущими к благу в них; несчастнейшие — те, кто больше всего пренебрегает этими причинами.'),('فالأسباب محل الأمر والنهي، والثواب والعقاب، والنجاح والخسران. وبالأسباب عرف الله، وبها عبد، وبها أطيع، وبها تقرب إليه المتقربون، وبها نال أولياؤه رضاه وجواره في جنته، وبها نصر حزبه دينه، وأقاموا دعوته، وبها أرسل رسله وشرع شرائعه، وبها انقسم الناس إلى سعيد وشقي، ومهتد وغوي، فالوقوف معها والالتفات إليها والنظر إليها هو الواجب شرعا، كما هو الواقع قدرا.','Причины — то, к чему относятся повеления и запреты, награда и наказание, успех и убыток. Посредством причин познают Аллаха, поклоняются Ему и повинуются Ему; через них стремящиеся к близости приближаются к Нему, Его приближённые достигают Его довольства и соседства с Ним в Раю, Его сторонники поддерживают Его религию и утверждают Его призыв. Посредством причин Он послал Своих посланников и установил Свои законы. Из-за них люди разделились на счастливых и несчастных, следующих верному руководству и заблудших. Считаться с причинами, обращать на них внимание и рассматривать их — обязанность по Закону, как это и происходит в силу предопределения.'),('ولا تكن ممن غلظ حجابه، وكثف طبعه فيقول: لا نقف معها وقوف من يعتقد أنها مستقلة بالإحداث والتأثير، وأنها أرباب من دون الله. فإن وجدت أحدا يزعم ذلك، ويظن أنها أرباب وآلهة مع الله مستقلة بالإيجاد، وأنها عون لله يحتاج في فعله إليها، رآها شركاء له= فشأنك به، فمزق أديمه، وتقرب إلى الله بعداوته ما استطعت، وإلا فما هذا النفي لما أثبته الله؟ والإلغاء لما اعتبره؟ والإهدار لما حققه؟ والحط والوضع لما نصبه؟ والمحو لما كتبه؟ والعزل لما ولاه؟ فإن زعمت أنك تعزلها عن رتبة الإلهية فسبحان الله! من','Не будь из тех, чья завеса стала плотной, а природа — грубой, кто говорит: «Мы не считаемся с ними так, как тот, кто полагает, что они самостоятельно создают и воздействуют и являются господами помимо Аллаха». Если найдёшь того, кто утверждает это и считает причины господами и божествами наряду с Аллахом, самостоятельно дающими существование, и помощью, в которой Аллах нуждается в Своих действиях, и видит в них Его сотоварищей, — тогда займись им, сорви с него покров и приближайся к Аллаху враждой к нему, насколько можешь. Иначе зачем отрицать то, что Аллах утвердил, отменять то, что Он принял в расчёт, отбрасывать то, чему Он придал силу, принижать и низвергать то, что Он установил, стирать то, что Он записал, и отстранять от полномочий то, чему Он их дал? Если ты утверждаешь, что отстраняешь причины от степени божественности, то — пречист Аллах! — кто')])
p(385,[('ولاها هذه الرتبة حتى تجعل كدك في عزلها؟','наделил их этой степенью, чтобы ты тратил все силы на их отстранение?'),('وبالله! لما أجهل كثيرا من أهل الكلام والتصوف، حيث لم يكن عندهم تحقيق التوحيد إلا إلغاءها ومحوها، وإهدارها بالكلية، وأنه لم يجعل الله في المخلوقات قوى ولا طبائع ولا غرائز لها تأثير بوجه ما، ولا في النار حرارة ولا إحراق، ولا في الدواء قوة، ولا في الخبز قوة مشبعة، ولا في الماء قوة مروية، ولا في العين قوة باصرة، ولا في الأنف قوة شامة، ولا في السم قوة قاتلة، ولا في الحديد قوة قاطعة؟ وأن الله لم يفعل شيئا بشيء، ولا فعل شيئا لأجل شيء.','Клянусь Аллахом, сколь невежественны многие приверженцы калама и суфизма! Для них осуществление единобожия заключается лишь в отмене причин, их устранении и полном отвержении. Они утверждают, что Аллах не вложил в творения ни сил, ни природных свойств, ни врождённых особенностей, которые хоть как-то воздействуют: в огонь — тепла и способности сжигать, в лекарство — силы, в хлеб — насыщающей силы, в воду — утоляющей жажду силы, в глаз — способности видеть, в нос — способности обонять, в яд — силы убивать, в железо — силы резать. И будто Аллах не совершил ничего посредством чего-либо и не совершил ничего ради чего-либо.'),('فهذا غاية توحيدهم الذي يحومون حوله، ويبالغون في تقريره.','Вот вершина их единобожия, вокруг которого они ходят и которое всячески стремятся утвердить.'),('ولعمر الله لقد أضحكوا عليهم العقلاء، وأشمتوا بهم الأعداء، ونهجوا لأعداء الرسل طريق إساءة الظن بهم، وجنوا على الإسلام والقرآن أعظم جناية، وقالوا: نحن أنصار الله ورسوله، الموكلون بكسر أعداء الإسلام وأعداء الرسل. ولعمر الله لقد كسروا الدين وسلطوا عليه المبطلين. وقد قيل: إياك ومصاحبة الجاهل، فإنه يريد أن ينفعك فيضرك.','Клянусь жизнью Аллаха! Они дали разумным людям повод смеяться над ними, врагам — злорадствовать над ними и проложили врагам посланников путь к дурным мыслям о них. Они совершили величайшее преступление против ислама и Корана, говоря: «Мы — помощники Аллаха и Его Посланника, которым поручено сокрушать врагов ислама и врагов посланников». Но, клянусь жизнью Аллаха, они сокрушили религию и дали приверженцам лжи власть над ней. Сказано: «Остерегайся дружбы с невеждой: он хочет принести тебе пользу, но вредит».'),('فقف مع الأسباب حيث أمرت بالوقوف، وفارقها حيث أمرت بمفارقتها، كما فارقها الخليل وهو في تلك الهوة من المنجنيق، حيث عرض له [جبريل] أقوى الأسباب، فقال: ألك حاجة؟ فقال: أما إليك فلا.','Так считаться с причинами следует там, где тебе велено с ними считаться, и оставлять их там, где тебе велено их оставить. Так особый друг Аллаха оставил их, находясь в той пропасти после броска из катапульты, когда перед ним предстал [Джибриль] — сильнейшая из причин — и спросил: «Есть ли у тебя нужда?» Он ответил: «В тебе — нет».')])
merge('v4-p382-04','v4-p383-01');merge('v4-p383-07','v4-p384-01');merge('v4-p384-03','v4-p385-01')
p(386,[('ودر معها حيث دارت، ناظرا إلى من أزمتها بيديه، والتفت إليها التفات العبد المأمور إلى تنفيذ ما أمر به والتحديق نحوه، وارعها حق رعايتها، ولا تغب عنها ولا تفن عنها، بل انظر إليها وهي في رتبتها التي أنزلها الله إياها.','Следуй за ними, куда бы они ни повернули, взирая на Того, в Чьих руках их поводья. Обращай на них внимание, как раб, которому велено исполнить приказ и пристально следить за его исполнением. Заботься о них должным образом, не переставай их замечать и не утрачивай их из восприятия, а рассматривай их на той ступени, на которую их поставил Аллах.'),('واعلم أن غيبتك بمسببها عنها نقص في عبوديتك، بل الكمال أن تشهد المعبود، وتشهد قيامك بعبوديته، وتشهد أن قيامك به لا بك، ومنه لا منك، وبحوله وقوته لا بحولك وقوتك. ومتى خرجت عن ذلك وقعت في انحرافين، لا بد لك من أحدهما: إما أن تغيب بها عن المقصود لذاته، لضعف نظرك وعقلك، وقصور علمك ومعرفتك، وإما أن تغيب بالمقصود عنها، بحيث لا تلتفت إليها. والكمال أن يسلمك الله من الانحرافين، فتبقى عبدا ملاحظا للعبودية، ناظرا إلى المعبود، والله المستعان، وعليه التكلان، ولا حول ولا قوة إلا بالله.','Знай: когда Тот, Кто устанавливает причины, поглощает тебя так, что ты перестаёшь замечать сами причины, это недостаток твоего рабского служения. Совершенство — созерцать Того, Кому поклоняешься, замечать своё исполнение рабского служения Ему и сознавать, что ты исполняешь его благодаря Ему, а не себе, что оно от Него, а не от тебя, совершается Его мощью и силой, а не твоими. Выйдя за эти пределы, ты неизбежно впадёшь в одно из двух отклонений: либо причины отвлекут тебя от Того, Кто является целью Сам по Себе, из-за слабости твоего взгляда и разума, недостатка знания и познания; либо Цель поглотит тебя так, что ты перестанешь замечать причины и обращать на них внимание. Совершенство — в том, чтобы Аллах уберёг тебя от обоих отклонений, и ты оставался рабом, который замечает своё рабское служение и взирает на Того, Кому поклоняется. У Аллаха испрашивают помощь, на Него уповают. Нет мощи и силы иначе как с Аллахом.')])
p(387,[('فصل','Раздел'),('قال شيخ الإسلام: (باب الوجود. أطلق الله تعالى في القرآن اسم الوجود صريحا في مواضع، فقال: {يَجِدِ اللَّهَ غَفُورًا رَحِيمًا} [النساء: 110]، {لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا} [النساء: 64]، {وَوَجَدَ اللَّهَ عِنْدَهُ} [النور: 39]. الوجود: الظفر بحقيقة الشيء، وهو اسم لثلاثة معان، أولها: وجود علم لدني، يقطع علوم الشواهد في صحة مكاشفة الحق إياك، والثاني: وجود الحق وجود عين منقطعا عن مساغ الإشارة، والثالث: وجود مقام اضمحلال رسم الوجود فيه بالاستغراق في الأولية).','Шейх аль-ислам сказал: «Глава об обретении. Всевышний Аллах прямо употребил в Коране название обретения в нескольких местах, сказав: {يَجِدِ اللَّهَ غَفُورًا رَحِيمًا} — “Найдёт Аллаха Прощающим, Милосердным” [“Ан-Ниса”, 4:110]; {لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا} — “Они нашли бы Аллаха Принимающим покаяние, Милосердным” [“Ан-Ниса”, 4:64]; {وَوَجَدَ اللَّهَ عِنْدَهُ} — “И найдёт возле себя Аллаха” [“Ан-Нур”, 24:39]. Обретение — достижение подлинной сути вещи. Это название трёх смыслов. Первый — обретение непосредственно дарованного знания, пресекающего знания свидетельств при достоверном раскрытии тебе Истинного. Второй — обретение Истинного в непосредственном видении, за пределами того, что доступно указанию. Третий — обретение стоянки, на которой след существования растворяется вследствие погружения в первичность».'),('هذا الباب هو العلم الذي شمر إليه القوم، والغاية التي قصدوها، ولا ريب أنهم قصدوا معنى صحيحا، وعبروا عنه بالوجود، واستدلوا عليه بهذه الآيات ونظيرها، ولكن ليس مقصودهم ما تضمنه الوجدان في هذه الآيات، فإنه وجدان لمطلوب تعلق باسم أو صفة، قال تعالى: {وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنْفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا} [النساء: 64]، فهذا وجود مقيد بظفرهم بمغفرة الله ورحمته لهم. وكذلك قوله: {وَمَنْ يَعْمَلْ سُوءًا أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللَّهَ','Эта глава — вершина, к которой устремились люди пути, и цель, к которой они стремились. Нет сомнения, что они подразумевали верный смысл, выразили его словом «обретение» и приводили в доказательство эти и подобные аяты. Однако их цель — не то, что заключено в слове «находить» в этих аятах: в них речь о нахождении искомого, связанного с именем или атрибутом. Всевышний сказал: {وَلَوْ أَنَّهُمْ إِذْ ظَلَمُوا أَنْفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا} — «Если бы они, поступив несправедливо к самим себе, пришли к тебе и попросили у Аллаха прощения, и Посланник попросил бы прощения для них, то они нашли бы Аллаха Принимающим покаяние, Милосердным» [«Ан-Ниса», 4:64]. Это обретение ограничено тем, что они достигают прощения Аллаха и Его милости к ним. Подобны этому Его слова: {وَمَنْ يَعْمَلْ سُوءًا أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللَّهَ')])
p(388,[('يَجِدِ اللَّهَ غَفُورًا رَحِيمًا} [النساء: 110]، ومعناه: أنه يجد ما ظنه من مغفرة الله، فيجد مغفرة الله له حاصلة. وكذلك: {وَوَجَدَ اللَّهَ عِنْدَهُ فَوَفَّاهُ حِسَابَهُ} [النور: 39]، فهذا وجدان الكافر لربه عند حسابه له على أعماله، وليس هذا هو الوجود الذي يشير إليه القوم، بل منه الأثر المعروف: «ابن آدم، اطلبني تجدني، فإن وجدتني وجدت كل شيء، وإن فتك فاتك كل شيء، وأنا أحب إليك من كل شيء»، ومنه الحديث: «أنا عند ظن عبدي بي»، ومنه الأثر الإسرائيلي: أن موسى عليه السلام قال: يا رب أين أجدك؟ قال: عند المنكسرة قلوبهم من أجلي.','يَجِدِ اللَّهَ غَفُورًا رَحِيمًا} — «Кто совершит зло или поступит несправедливо к себе, а затем попросит у Аллаха прощения, тот найдёт Аллаха Прощающим, Милосердным» [«Ан-Ниса», 4:110]. Это означает: он найдёт то прощение Аллаха, на которое рассчитывал, и обнаружит, что прощение Аллаха действительно получено им. Подобны этому слова: {وَوَجَدَ اللَّهَ عِنْدَهُ فَوَفَّاهُ حِسَابَهُ} — «И найдёт возле себя Аллаха, Который сполна произведёт с ним расчёт» [«Ан-Нур», 24:39]. Здесь неверующий находит своего Господа, когда Тот производит с ним расчёт за его дела. Это не то обретение, на которое указывают люди пути. К нему относится известное предание: «Сын Адама! Ищи Меня — найдёшь Меня. Если найдёшь Меня, найдёшь всё; если упустишь Меня, упустишь всё. И Я любимее для тебя, чем всё остальное». К нему относится и хадис: «Я таков, каким Меня считает Мой раб», а также предание от сынов Исраиля о том, что Муса, мир ему, спросил: «Господи, где мне найти Тебя?» Он ответил: «У тех, чьи сердца сокрушены ради Меня».'),('ومنه الحديث الصحيح: «إن الله تعالى يقول يوم القيامة: عبدي، استطعمتك فلم تطعمني، قال: يا رب كيف أطعمك وأنت رب العالمين؟ قال: استطعمك عبدي فلان فلم تطعمه، أما لو أطعمته لوجدت ذلك عندي. عبدي، استسقيتك فلم تسقني، قال: يا رب كيف أسقيك وأنت رب العالمين؟ قال: استسقاك عبدي فلان فلم تسقه، أما لو سقيته لوجدت ذلك عندي. عبدي، مرضت فلم تعدني، قال: يا رب كيف أعودك وأنت رب العالمين؟ قال: مرض عبدي فلان فلم تعده، أما لو عدته لوجدتني عنده».','К нему относится и достоверный хадис: «Поистине, Всевышний Аллах скажет в День воскресения: “Раб Мой! Я просил тебя накормить Меня, но ты Меня не накормил”. Тот скажет: “Господи! Как я мог накормить Тебя, когда Ты — Господь миров?” Он скажет: “Такой-то Мой раб просил тебя накормить его, но ты его не накормил. Если бы ты накормил его, ты нашёл бы это у Меня. Раб Мой! Я просил тебя напоить Меня, но ты Меня не напоил”. Тот скажет: “Господи! Как я мог напоить Тебя, когда Ты — Господь миров?” Он скажет: “Такой-то Мой раб просил тебя напоить его, но ты его не напоил. Если бы ты напоил его, ты нашёл бы это у Меня. Раб Мой! Я заболел, но ты Меня не навестил”. Тот скажет: “Господи! Как я мог навестить Тебя, когда Ты — Господь миров?” Он скажет: “Такой-то Мой раб заболел, но ты его не навестил. Если бы ты навестил его, ты нашёл бы Меня у него”».'),('فتأمل قوله في الإطعام والإسقاء: «لوجدت ذلك عندي» أي: لوجدت','Обрати внимание: о кормлении и поении Он сказал «Ты нашёл бы это у Меня», то есть нашёл бы')])
merge('v4-p387-03','v4-p388-01')
D['boundary_notes']=[{'printed_page':379,'position':'start','note':'Самостоятельный абзац «والمقصود» после законченного абзаца378;378 просмотрена только для контекста, слияние не требуется.'},{'printed_page':388,'position':'end','source_id':'v4-p388-03','continuation_page':389,'note':'Последний абзац продолжается на389 словами «جزاءه وثوابه عندي».389 просмотрена для контекста, не импортирована. Переведён только фрагмент388; требуется объединить с первым исходным фрагментом389.'}]
